head.script:
// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
//
// ********************************************************************

scwin.gReqAcptNo;
scwin.gAnsRnd;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
X < !정보--;
셋팅-- > function() {
    scwin.gEmpNo = js_emp_no; // 세션정보

    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gAnsRnd = $c.frame.path("../").scwin.gAnsRnd;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert("자식창:"+gAcptNo+","+ gIsurCd);

    txb_com_abbrv.setValue($c.frame.path("../").txb_com_abbrv.getValue());
    txb_emp_nm.setValue(js_emp_nm);
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);

        // hidden 추가 (ysh)
        txb_acptno.hide();
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_inquiry",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_inquiry=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        $c.stf.doLogSave('ULDSTF30203.xml', SCREN_PROCS_TP_CD_01);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_cls_dd_onclick
 * @description img_cls_dd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_cls_dd_onclick = function() {
    try {
        popUpCalendar2(edt_deadline_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30203.img_cls_dd_onclick" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description img_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    try {
        const winTitle = txb_com_abbrv.getValue() + " / 수시공시 제출현황";
        const url = "/dsclmgt/ULDSTF30204.gfm";
        await $c.frame.CreateFrame("DSCLLIST" + scwin.gIsurCd, url, winTitle, 70, 10, 630, 330 + 30, "window", 0, 0, true);
        /*
        var url = "/dsclmgt/ULDSTF30204.gfm?";
        	url += "&ISUR_CD=" + gIsurCd;
        	url += "&frameID=" + frame.FrameID;
        //frame.Provider("/top").GWinOpen("child01", url, winTitle, 100, 20, 790, 460+30,"");
        //frame.Provider("/top").WinOpen("DSCLLIST"+gIsurCd,  url, winTitle, 790, 460+30);
         */
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.img_search_onclick" });
    }
};

/**
 * @method
 * @name trs_inquiry_OnSuccess
 * @description inquiry On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.trs_inquiry_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_inquiry_OnFail
 * @description inquiry On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_inquiry_OnFail = async function() {
    try {
        await $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.trs_inquiry_OnFail" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30203.btn_Save_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    const vDeadlineDd = edt_deadline_dd.getValue();
    if (vDeadlineDd.length < 8) {
        await $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_deadline_dd.focus();
        return;
    }
    const vAnsAcptNo = txb_acptno.getValue();
    if (vAnsAcptNo.length !== 14) {
        await $c.win.alert("답변공시를 선택하여 올바르게 입력하시오.");
        return;
    }
    dts_inquiry.insertRow();
    dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
    dts_inquiry.setCellData(1, "ANS_ACPT_NO", txb_acptno.getValue());
    dts_inquiry.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_inquiry.setCellData(1, "ADM_DEADLINE", vDeadlineDd);
    dts_inquiry.setCellData(1, "FINAL_YN", cmb_final_yn.getValue());
    dts_inquiry.setCellData(1, "REMK", txa_remk.getValue());
    // alert(dts_nfaith.text);

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_inquiry.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_inquiry",
            action : "/InquiryDisclosure.do",
            ref : "dts_inquiry",
            target : "trs_inquiry=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
